  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (query.trim()) {
      onSearch(query);
    }
  };

  const isDocked = style === 'docked';
  const borderRadius = isDocked ? 'var(--radius)' : '9999px';

  return (
    <form onSubmit={handleSubmit} className={`w-full ${isDocked ? 'max-w-none px-4 md:px-8' : 'max-w-3xl px-4 md:px-0'} mx-auto relative z-10`}>
      <div className={`relative group/input`}>

        {/* AI Mode Lighting Effects */}
        {!isDocked && (
            <>
               {/* Layer 1: Deep Ambient Aura (Atmospheric Glow - Strictly Theme Colors) */}
               <div 
                  className="absolute -inset-12 rounded-[inherit] bg-gradient-to-r from-primary/30 via-secondary/10 to-primary/30 opacity-0 group-hover/input:opacity-30 group-focus-within/input:opacity-100 blur-3xl transition-opacity duration-700 ease-silky animate-pulse-slow pointer-events-none"
                  style={{ borderRadius: borderRadius }}
               />

               {/* Layer 2: Beam Bloom (Soft Halo behind the sharp edge) */}
               <div 
                  className="absolute -inset-[3px] rounded-[inherit] opacity-20 group-hover/input:opacity-40 group-focus-within/input:opacity-60 transition-opacity duration-500 z-0 pointer-events-none overflow-hidden blur-sm"
                  style={{ 
                      borderRadius: borderRadius,
                      mask: 'linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)',
                      maskComposite: 'exclude',
                      WebkitMask: 'linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)',
                      WebkitMaskComposite: 'xor',
                      padding: '3px'
                  }}
               >
                   <div 
                        className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[200%] h-[200%] animate-[spin_4s_linear_infinite]"
                        style={{
                            background: `conic-gradient(from 0deg, transparent 0%, transparent 40%, rgb(var(--color-secondary)) 50%, white 55%, rgb(var(--color-primary)) 60%, transparent 100%)`
                        }}
                   />
               </div>

               {/* Layer 3: Sharp Chasing Beam (White Hot Core) */}
               <div 
                  className="absolute -inset-[1.5px] rounded-[inherit] opacity-40 group-hover/input:opacity-70 group-focus-within/input:opacity-100 transition-opacity duration-300 z-0 pointer-events-none overflow-hidden"
                  style={{ 
                      borderRadius: borderRadius,
                      mask: 'linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)',
                      maskComposite: 'exclude',
                      WebkitMask: 'linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0)',
                      WebkitMaskComposite: 'xor',
                      padding: '1.5px' 
                  }}
               >
                   {/* Spinning Conic Gradient Beam */}
                   <div 
                        className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[200%] h-[200%] animate-[spin_4s_linear_infinite]"
                        style={{
                            background: `conic-gradient(from 0deg, transparent 0%, transparent 45%, rgb(var(--color-secondary)) 50%, white 52%, white 55%, rgb(var(--color-primary)) 60%, transparent 100%)`
                        }}
                   />
               </div>
            </>
        )}

        {/* Main Input Container */}
        <div 
            className={`
                relative flex items-center z-10
                bg-white/[var(--bg-opacity)] dark:bg-black/[var(--bg-opacity)] 
                backdrop-blur-[var(--blur)] 
                border border-zinc-200 dark:border-white/10
                transition-all duration-500 ease-liquid
                group-focus-within/input:border-white/20
                group-focus-within/input:shadow-[0_0_30px_-10px_rgba(var(--color-primary),0.3)]
                group-hover/input:border-zinc-300 dark:group-hover/input:border-white/20
                shadow-xl
            `}
            style={{ borderRadius: borderRadius }}
        >

          <input
            type="search"
            enterKeyHint="search"
            className="w-full bg-transparent text-zinc-900 dark:text-white px-6 py-6 focus:outline-none placeholder-zinc-400 dark:placeholder-zinc-500 font-medium text-xl transition-all duration-300 ease-liquid text-left appearance-none relative z-10"
            placeholder="Ask any song..."
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            disabled={isLoading}
            autoComplete="off"
            autoCorrect="off"
            spellCheck="false"
            style={{ borderRadius: borderRadius }}
          />

        </div>
      </div>
    </form>
  );
};
]]></content>
</change>

