          id: `stanza-${stanzas.length}`,
          lines: currentLines,
          headerText: currentHeader,
          isTitle: false,
          type: currentType
        });
        currentLines = [];
      }
    };

    lines.forEach((line) => {
      const trimmed = line.trim();
      if (!trimmed) {
        flushStanza();
        return;
      }

      // Detect Headers
      const headerMatch = trimmed.match(/^\[(Verse|Chorus|Bridge|Pre-Chorus|Outro|Intro|Hook|Instrumental|Solo)(.*?)\]/i);

      if (headerMatch) {
        flushStanza();
        currentHeader = trimmed.replace('[', '').replace(']', '');
        const typeStr = headerMatch[1].toLowerCase();

        if (typeStr.includes('chorus')) currentType = 'chorus';
        else if (typeStr.includes('bridge')) currentType = 'bridge';
        else if (typeStr.includes('pre-chorus')) currentType = 'pre-chorus';
        else if (typeStr.includes('outro')) currentType = 'outro';
        else if (typeStr.includes('intro')) currentType = 'intro';
        else if (typeStr.includes('instrumental') || typeStr.includes('solo')) currentType = 'instrumental';
        else if (typeStr.includes('verse')) currentType = 'verse';
        else currentType = 'other';
      } else {
        currentLines.push(trimmed);
      }
    });
    flushStanza();
    return stanzas;
  }, [data.text, translatedText]);

  // Flattened lines for Karaoke
  const karaokeLines = useMemo(() => {
    const lines: { text: string; id: string; isHeader: boolean }[] = [];
    parsedLyrics.forEach((stanza, sIdx) => {
      if (stanza.headerText) {
          lines.push({ text: stanza.headerText, id: `k-header-${sIdx}`, isHeader: true });
      }
      stanza.lines.forEach((line, lIdx) => {
        lines.push({ text: line, id: `k-line-${sIdx}-${lIdx}`, isHeader: false });
      });
    });
    return lines;
  }, [parsedLyrics]);

  // Snippet Highlighting
  const matchedLineId = useMemo(() => {
    if (!data.metadata?.matchedSnippet) return null;
    const cleanSnippet = data.metadata.matchedSnippet.toLowerCase().replace(/[^a-z0-9]/g, '');

    for (let sIdx = 0; sIdx < parsedLyrics.length; sIdx++) {
      const stanza = parsedLyrics[sIdx];
      for (let lIdx = 0; lIdx < stanza.lines.length; lIdx++) {
        const line = stanza.lines[lIdx];
        const cleanLine = line.toLowerCase().replace(/[^a-z0-9]/g, '');
        if (cleanLine.includes(cleanSnippet)) {
          return `line-${sIdx}-${lIdx}`;
        }
      }
    }
    return null;
  }, [parsedLyrics, data.metadata?.matchedSnippet]);

  // Auto-scroll to matched snippet
  useEffect(() => {
    if (matchedLineId && !isKaraokeMode) {
      setTimeout(() => {
        const el = document.getElementById(matchedLineId);
        if (el) {
          el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        }
      }, 500);
    }
  }, [matchedLineId, isKaraokeMode]);

  // Karaoke Auto-Advance
  useEffect(() => {
    if (isPlaying && isKaraokeMode) {
      autoScrollInterval.current = window.setInterval(() => {
        setActiveLineIndex((prev) => {
          const next = prev + 1;
          if (next >= karaokeLines.length) {
             setIsPlaying(false);
             return prev;
          }
          return next;
        });
      }, 3000 / playbackSpeed); // Basic timing
    } else {
      if (autoScrollInterval.current) {
        clearInterval(autoScrollInterval.current);
      }
    }
    return () => {
      if (autoScrollInterval.current) clearInterval(autoScrollInterval.current);
    };
  }, [isPlaying, isKaraokeMode, karaokeLines.length, playbackSpeed]);

  // Karaoke Scroll Sync
  useEffect(() => {
    if (isKaraokeMode && karaokeLines.length > 0) {
       const activeEl = document.getElementById(`k-line-active-${activeLineIndex}`);
       if (activeEl) {
         activeEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
       }
    }
  }, [activeLineIndex, isKaraokeMode, karaokeLines]);

  // Copy Logic
  const handleCopy = () => {
    const text = translatedText || data.text;
    navigator.clipboard.writeText(text).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    });
  };

  // Download Logic
  const handleDownload = () => {
    const text = translatedText || data.text;
    const title = data.metadata?.title || 'Unknown Song';
    const blob = new Blob([text], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${title} - Lyrics.txt`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // Back to Top Visibility
  useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY > 300) setShowBackToTop(true);
      else setShowBackToTop(false);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

