  const getAudioContext = () => {
    if (!audioCtxRef.current) {
        audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    }
    if (audioCtxRef.current.state === 'suspended') {
        audioCtxRef.current.resume();
    }
    return audioCtxRef.current;
  };

  // --- Synthetic Sound Engine ---
  const triggerFeedback = useCallback((type: FeedbackType = 'tap') => {
    // 1. Audio Feedback
    if (soundEnabled) {
        try {
            const ctx = getAudioContext();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            const now = ctx.currentTime;

            osc.connect(gain);
            gain.connect(ctx.destination);

            if (type === 'tap' || type === 'light') {
                // Short high tick
                osc.type = 'sine';
                osc.frequency.setValueAtTime(800, now);
                osc.frequency.exponentialRampToValueAtTime(300, now + 0.05);
                gain.gain.setValueAtTime(0.05, now);
                gain.gain.exponentialRampToValueAtTime(0.001, now + 0.05);
                osc.start(now);
                osc.stop(now + 0.05);
            } else if (type === 'toggle') {
                // Mechanical double click
                osc.type = 'triangle';
                osc.frequency.setValueAtTime(400, now);
                gain.gain.setValueAtTime(0.05, now);
                gain.gain.linearRampToValueAtTime(0, now + 0.03);
                osc.start(now);
                osc.stop(now + 0.04);
            } else if (type === 'success') {
                // Pleasing Major Chord Arpeggio
                const notes = [523.25, 659.25, 783.99]; // C Major
                notes.forEach((freq, i) => {
                    const o = ctx.createOscillator();
                    const g = ctx.createGain();
                    o.type = 'sine';
                    o.frequency.value = freq;
                    o.connect(g);
                    g.connect(ctx.destination);
                    g.gain.setValueAtTime(0, now);
                    g.gain.linearRampToValueAtTime(0.05, now + 0.05 + (i * 0.05));
                    g.gain.exponentialRampToValueAtTime(0.001, now + 0.4 + (i * 0.05));
                    o.start(now + (i * 0.05));
                    o.stop(now + 0.5 + (i * 0.05));
                });
            } else if (type === 'error') {
                // Low descending buzz
                osc.type = 'sawtooth';
                osc.frequency.setValueAtTime(150, now);
                osc.frequency.linearRampToValueAtTime(50, now + 0.3);
                gain.gain.setValueAtTime(0.05, now);
                gain.gain.linearRampToValueAtTime(0, now + 0.3);
                osc.start(now);
                osc.stop(now + 0.3);
            } else if (type === 'gamewin') {
                // Uplifting Sweep
                osc.type = 'sine';
                osc.frequency.setValueAtTime(200, now);
                osc.frequency.exponentialRampToValueAtTime(800, now + 0.5);
                gain.gain.setValueAtTime(0.05, now);
                gain.gain.linearRampToValueAtTime(0, now + 0.5);
                osc.start(now);
                osc.stop(now + 0.5);
            }
        } catch (e) {
            console.warn("Audio playback failed", e);
        }
    }

    // 2. Haptic Feedback
    if (hapticEnabled && navigator.vibrate) {
        if (type === 'tap' || type === 'light') navigator.vibrate(8); // Crisp tick
        else if (type === 'toggle') navigator.vibrate(15); // Solid thump
        else if (type === 'success') navigator.vibrate([10, 30, 10]); // Double tap
        else if (type === 'error') navigator.vibrate([50, 30, 50]); // Buzz
        else if (type === 'gamewin') navigator.vibrate([10, 50, 10, 50, 10]); // Party
    }
  }, [soundEnabled, hapticEnabled]);

  // --- Effects & Logic ---

  // History Persistence
  const [history, setHistory] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('lyricist_history');
      if (!saved) return [];
      const parsed = JSON.parse(saved);
      if (!Array.isArray(parsed)) return [];
      return parsed.filter((item: any) => typeof item === 'string');
    } catch { return []; }
  });

  useEffect(() => {
    localStorage.setItem('lyricist_history', JSON.stringify(history));
  }, [history]);

  useEffect(() => {
    localStorage.setItem('lyricist_recommendations', JSON.stringify(recommendationPool));
  }, [recommendationPool]);

  useEffect(() => {
    localStorage.setItem('lyricist_favorites', JSON.stringify(favorites));
  }, [favorites]);

  useEffect(() => {
    localStorage.setItem('lyricist_fav_sort', favSortOrder);
  }, [favSortOrder]);

  // PWA Install Prompt
  useEffect(() => {
    const handleBeforeInstallPrompt = (e: any) => {
      e.preventDefault();
      setDeferredPrompt(e);
    };
    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    return () => window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
  }, []);

  const handleInstallClick = () => {
    if (deferredPrompt) {
      deferredPrompt.prompt();
      deferredPrompt.userChoice.then((choiceResult: any) => {
        if (choiceResult.outcome === 'accepted') {
          console.log('User accepted the A2HS prompt');
        }
        setDeferredPrompt(null);
      });
    }
  };

  // Deep Linking
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const q = params.get('q');
    if (q) {
      setSearchQuery(q);
      handleSearch(q);
    }
  }, []);

  // Update CSS Variables for Customization
  useEffect(() => {
    const root = document.documentElement;

    // Theme Mode
    if (theme === 'dark') root.classList.add('dark');
    else root.classList.remove('dark');

    // Accent Colors
    if (accent === 'custom') {
        root.style.setProperty('--color-primary', customPrimary);
        root.style.setProperty('--color-secondary', customSecondary);
    } else {
        root.style.setProperty('--color-primary', ACCENT_COLORS[accent].primary);
        root.style.setProperty('--color-secondary', ACCENT_COLORS[accent].secondary);
    }

    // Border Radius
    const radiusMap = {
        round: { lg: '1.5rem', sm: '0.75rem' },
        soft: { lg: '2rem', sm: '9999px' }, // Pill shapes for inputs/buttons in Soft mode
        sharp: { lg: '0.25rem', sm: '0.125rem' }
    };
    root.style.setProperty('--radius', radiusMap[borderRadius].lg);
    root.style.setProperty('--radius-sm', radiusMap[borderRadius].sm);

    // Card Style (Glass/Solid/Liquid)
    if (cardStyle === 'solid') {
        root.style.setProperty('--bg-opacity', '0.95');
        root.style.setProperty('--blur', '0px');
        document.body.classList.add('style-solid');
        document.body.classList.remove('style-liquid');
    } else if (cardStyle === 'liquid-glass') {
        root.style.setProperty('--bg-opacity', '0.01'); // Ultra transparent
        root.style.setProperty('--blur', '0px');        // Crystal clear
        document.body.classList.add('style-liquid');
        document.body.classList.remove('style-solid');
    } else {
        // Standard Glass
        root.style.setProperty('--bg-opacity', theme === 'dark' ? '0.4' : '0.6');
        root.style.setProperty('--blur', blurStrength === 'high' ? '40px' : blurStrength === 'medium' ? '24px' : '12px');
        document.body.classList.remove('style-solid', 'style-liquid');
    }

    // Animations
    root.style.setProperty('--anim-speed', animSpeed === 'slow' ? '1.5' : animSpeed === 'fast' ? '0.6' : '1');

    // Fonts & Scale
    const fontMap = { sans: 'Inter, sans-serif', serif: 'Merriweather, serif', mono: 'JetBrains Mono, monospace' };
    root.style.fontFamily = fontMap[fontStyle];
    root.style.fontSize = `${uiScale}%`;

    // Content Align
    root.style.setProperty('--text-align', contentAlign);

  }, [theme, accent, customPrimary, customSecondary, cardStyle, blurStrength, animSpeed, fontStyle, uiScale, borderRadius, contentAlign]);

  // Scroll Visibility Logic
  useEffect(() => {
    const handleScroll = () => {
      const currentScrollY = window.scrollY;

      if (currentScrollY <= 50) {
          setIsSearchBarVisible(true);
      } else {
          // If scrolling DOWN, Hide. If scrolling UP, Show.
          if (currentScrollY > lastScrollY.current) {
              setIsSearchBarVisible(false);
          } else {
              setIsSearchBarVisible(true);
          }
      }
      lastScrollY.current = currentScrollY;
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const handleSearch = async (query: string) => {
    if (!query.trim()) return;

    // Update URL for Deep Linking
    try {
        const url = new URL(window.location.href);
        url.searchParams.set('q', query);
        window.history.pushState({}, '', url);
    } catch (e) {
        // Ignore pushState errors in sandboxed environments
    }

    setSearchState(prev => ({ ...prev, status: 'loading', error: null }));

    // Add to history
    if (!history.includes(query)) {
      const newHistory = [query, ...history].slice(0, 10);
      setHistory(newHistory);
    }

    try {
      const result = await fetchLyrics(query);
      setSearchState({ status: 'success', data: result, error: null });
      triggerFeedback('success');

      // Update Recommendation Pool with result + related songs
      let newRecommendations = [...recommendationPool];

      // Add the found song itself
      if (result.metadata?.title && result.metadata?.artist) {
          const songKey = `${result.metadata.title} - ${result.metadata.artist}`;
          if (!newRecommendations.includes(songKey)) {
              newRecommendations.unshift(songKey);
          }
      }

      // Add related songs from metadata
      if (result.metadata?.relatedSongs) {
          result.metadata.relatedSongs.forEach(song => {
              if (!newRecommendations.includes(song)) {
                  newRecommendations.unshift(song);
              }
          });
      }

      // Keep pool manageable (max 50)
      setRecommendationPool(newRecommendations.slice(0, 50));

    } catch (err: any) {
      setSearchState({ status: 'error', data: null, error: err.message });
      triggerFeedback('error');
    }
  };

  const handleFavoriteToggle = (song: string) => {
      const newFavorites = favorites.includes(song)
