                <div className="absolute top-0 right-1/4 w-[500px] h-[500px] bg-secondary/20 dark:bg-secondary/10 rounded-full mix-blend-screen dark:mix-blend-screen blur-[120px] animate-blob animation-delay-2000 filter"></div>
                <div className="absolute -bottom-32 left-1/3 w-[600px] h-[600px] bg-purple-500/20 dark:bg-purple-900/20 rounded-full mix-blend-screen dark:mix-blend-screen blur-[120px] animate-blob animation-delay-4000 filter"></div>
                </>
            )}

            {/* Calm: Just Waves */}
            <div className={`absolute bottom-0 left-0 right-0 h-[30vh] opacity-30 dark:opacity-20`}>
                 {/* Waves removed as per previous request, but logic kept for extensibility */}
            </div>
        </div>
      )}

      {/* Main Content Area */}
      <div className={`relative z-10 flex flex-col min-h-[100dvh] ${layoutWidth === 'narrow' ? 'max-w-3xl' : layoutWidth === 'wide' ? 'max-w-[1600px]' : 'max-w-6xl'} mx-auto px-4 md:px-8`}>

        {/* Header */}
        <header 
            className="pt-8 pb-6 flex flex-col items-center justify-center text-center cursor-pointer transition-transform active:scale-95 ease-silky" 
            onClick={() => {
                if (searchState.status === 'idle') {
                    // Trigger Game Check
                    setEggClicks(prev => prev + 1);
                    if (eggClicks + 1 === 5) {
                        setIsEggGameOpen(true);
                        setEggClicks(0);
                        triggerFeedback('gamewin');
                    } else {
                        triggerFeedback('tap');
                    }
                } else {
                    resetApp();
                }
            }}
        >
          <h1 className="text-4xl md:text-6xl font-black tracking-tighter mb-2 bg-clip-text text-transparent bg-gradient-to-r from-primary via-secondary to-primary animate-gradient-xy bg-[length:200%_auto]">
            Lyricist
          </h1>
          <p className="text-zinc-500 dark:text-zinc-400 text-sm font-medium tracking-wide">
             Exact Lyrics Finder
          </p>
        </header>

        {/* Main View Switch */}
        <main className="flex-1 flex flex-col items-center w-full pb-40"> {/* Increased padding for bottom search bar */}

          {searchState.status === 'idle' && (
            <>
              <SongSuggestions 
                key={suggestionsKey} 
                songs={suggestedSongs} 
                onSelect={(q) => {
                    setSearchQuery(q);
                    handleSearch(q);
                }} 
              />
              <SearchHistory 
                history={history} 
                onSelect={(q) => {
                    setSearchQuery(q);
                    handleSearch(q);
                }} 
                onClear={() => {
                    setHistory([]);
                    localStorage.removeItem('lyricist_history');
                    triggerFeedback('tap');
                }} 
              />
            </>
          )}

          {searchState.status === 'loading' && (
            <div className="flex flex-col items-center justify-center min-h-[50vh] animate-fade-in">
              {/* Loader */}
              {loaderStyle === 'equalizer' ? (
                  <div className="flex items-end justify-center gap-1 h-[3.25rem] mb-6"> {/* Exact h-13 */}
                    {[...Array(9)].map((_, i) => (
                        <div 
                            key={i} 
                            className="w-1.5 bg-gradient-to-t from-primary to-secondary rounded-full animate-wave shadow-[0_0_10px_rgba(var(--color-primary),0.4)]"
                            style={{ animationDelay: `${i * 0.1}s`, height: '100%' }}
                        ></div>
                    ))}
                  </div>
              ) : (
                  // Orbit Loader
                  <div className="relative w-16 h-16 mb-6 animate-spin">
                      <div className="absolute top-0 left-0 w-full h-full border-4 border-zinc-200 dark:border-white/10 rounded-full"></div>
                      <div className="absolute top-0 left-0 w-full h-full border-4 border-primary rounded-full border-t-transparent animate-spin"></div>
                  </div>
              )}

              <p className="text-zinc-400 dark:text-zinc-500 font-medium animate-pulse text-sm mt-4">Loading...</p>
            </div>
          )}

          {searchState.status === 'success' && searchState.data && (
            <LyricsDisplay 
                data={searchState.data} 
                onSearch={handleSearch}
                isKaraokeMode={isKaraokeMode}
                setIsKaraokeMode={(v) => {
                    setIsKaraokeMode(v);
                    triggerFeedback(v ? 'gamewin' : 'tap');
                }}
                entranceAnim={entranceAnim}
                favorites={favorites}
                onToggleFavorite={handleFavoriteToggle}
            />
          )}

          {searchState.status === 'error' && (
            <div className="text-center mt-12 p-8 bg-red-50 dark:bg-red-900/10 border border-red-100 dark:border-red-900/20 rounded-[var(--radius)] animate-zoom-in max-w-lg">
              <div className="w-16 h-16 bg-red-100 dark:bg-red-900/20 rounded-full flex items-center justify-center mx-auto mb-4 text-red-500">
                 <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
              </div>
              <h2 className="text-xl font-bold text-red-600 dark:text-red-400 mb-2">Oops!</h2>
              <p className="text-zinc-600 dark:text-zinc-300">{searchState.error}</p>
              <button 
                onClick={resetApp}
                className="mt-6 px-6 py-2 bg-red-600 hover:bg-red-700 text-white font-medium rounded-full transition-all hover:scale-105 active:scale-95 ease-silky"
              >
                Try Again
              </button>
            </div>
          )}
        </main>

        {/* Floating Bottom Search Bar (Always visible unless scrolling down) */}
        {!isKaraokeMode && (
            <div 
                className={`fixed bottom-0 left-0 right-0 z-50 p-4 pb-6 transition-transform duration-500 ease-silky ${isSearchBarVisible ? 'translate-y-0' : 'translate-y-full'}`}
            >
                {/* Gradient fade behind search bar */}
                <div className="absolute inset-0 bg-gradient-to-t from-white via-white/90 to-transparent dark:from-black dark:via-black/90 dark:to-transparent pointer-events-none h-32 -top-16"></div>

                <SearchBar 
                    query={searchQuery} 
                    setQuery={setSearchQuery} 
                    onSearch={handleSearch} 
                    isLoading={searchState.status === 'loading'}
                    style={searchBarStyle}
                />
            </div>
        )}

      </div>

      {/* Global Buttons (Home & Settings) */}
      {!isKaraokeMode && (
          <>
            {/* Home Button */}
            <button
                onClick={() => {
                    // Logic: If on home screen, refresh suggestions. If deep in lyrics, go home.
                    if (searchState.status === 'idle') {
                        setSuggestionsKey(prev => prev + 1); // Refresh
                        triggerFeedback('success');
                    } else {
                        resetApp();
                    }
                }}
                className={`fixed top-6 left-6 z-40 p-3 rounded-full bg-white/[var(--bg-opacity)] dark:bg-black/[var(--bg-opacity)] backdrop-blur-[var(--blur)] shadow-lg border border-zinc-200 dark:border-white/10 text-zinc-600 dark:text-zinc-400 hover:text-primary transition-all duration-500 ease-silky hover:scale-110 active:scale-90 ${isSearchBarVisible ? 'translate-y-0 opacity-100' : '-translate-y-20 opacity-0'}`}
                title="Home / Refresh"
            >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" /></svg>
            </button>

            {/* Settings Button */}
            <button
                onClick={() => {
                    setIsSettingsOpen(true);
                    triggerFeedback('tap');
                }}
                className={`fixed top-6 right-6 z-40 p-3 rounded-full bg-white/[var(--bg-opacity)] dark:bg-black/[var(--bg-opacity)] backdrop-blur-[var(--blur)] shadow-lg border border-zinc-200 dark:border-white/10 text-zinc-600 dark:text-zinc-400 hover:text-primary transition-all duration-500 ease-silky hover:rotate-90 hover:scale-110 active:scale-90 ${isSearchBarVisible ? 'translate-y-0 opacity-100' : '-translate-y-20 opacity-0'}`}
                title="Settings"
            >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
            </button>
          </>
      )}

      {/* Settings Modal (Liquid Glass Style) */}
      {isSettingsOpen && (
        <div 
            className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-fade-in"
            onClick={() => setIsSettingsOpen(false)}
        >
            <div 
                className="w-full max-w-4xl h-[80vh] flex flex-col md:flex-row rounded-[var(--radius)] overflow-hidden animate-zoom-in bg-white/[var(--bg-opacity)] dark:bg-black/[var(--bg-opacity)] backdrop-blur-[var(--blur)] shadow-2xl border border-white/20"
                onClick={e => e.stopPropagation()}
            >
                {/* Sidebar Navigation */}
                <div className="w-full md:w-64 bg-zinc-50/50 dark:bg-white/5 border-r border-zinc-200 dark:border-white/5 flex flex-col">
                    <div className="p-6 border-b border-zinc-200 dark:border-white/5">
                        <h2 className="text-xl font-black text-zinc-900 dark:text-white tracking-tight">Settings</h2>
                    </div>
                    <nav className="flex-1 p-4 space-y-2 overflow-y-auto">
                        <button 
                            onClick={() => { setActiveSettingsTab('appearance'); triggerFeedback('tap'); }}
                            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-all ease-silky ${activeSettingsTab === 'appearance' ? 'bg-primary text-white shadow-lg shadow-primary/30' : 'text-zinc-600 dark:text-zinc-400 hover:bg-zinc-200 dark:hover:bg-white/10'}`}
                        >
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 21a4 4 0 01-4-4V5a2 2 0 012-2h4a2 2 0 012 2v12a4 4 0 01-4 4zm0 0h12a2 2 0 002-2v-4a2 2 0 00-2-2h-2.343M11 7.343l1.657-1.657a2 2 0 012.828 0l2.829 2.829a2 2 0 010 2.828l-8.486 8.485M7 17h.01" /></svg>
                            Appearance
                        </button>
                        <button 
                            onClick={() => { setActiveSettingsTab('general'); triggerFeedback('tap'); }}
                            className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-all ease-silky ${activeSettingsTab === 'general' ? 'bg-primary text-white shadow-lg shadow-primary/30' : 'text-zinc-600 dark:text-zinc-400 hover:bg-zinc-200 dark:hover:bg-white/10'}`}
                        >
                            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4m6 6v10m6-2a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4" /></svg>
                            General
                        </button>
