    return parsed.filter((item: any) => typeof item === 'string');
  } catch (e) { return []; }
};

const App: React.FC = () => {
  const [searchQuery, setSearchQuery] = useState('');
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [activeSettingsTab, setActiveSettingsTab] = useState<'appearance' | 'general' | 'system' | 'favorites'>('appearance');
  const [isKaraokeMode, setIsKaraokeMode] = useState(false);

  // Game State
  const [eggClicks, setEggClicks] = useState(0);
  const [isEggGameOpen, setIsEggGameOpen] = useState(false);
  const [gameScore, setGameScore] = useState(0);
  const [gameLevel, setGameLevel] = useState(1);
  const [questionsCorrect, setQuestionsCorrect] = useState(0);
  const [currentQuestion, setCurrentQuestion] = useState<{song: string, correct: string, options: string[]} | null>(null);
  const [gameTimer, setGameTimer] = useState(30); 
  const [gameState, setGameState] = useState<'playing' | 'gameover'>('playing');
  const [streak, setStreak] = useState(0);
  const [powerups, setPowerups] = useState({ split: 1, freeze: 1 });
  const [isFrozen, setIsFrozen] = useState(false);
  const [removedOptions, setRemovedOptions] = useState<string[]>([]);
  const [playedQuestions, setPlayedQuestions] = useState<Set<string>>(new Set());

  // PWA
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  // Data
  const [recommendationPool, setRecommendationPool] = useState<string[]>(getSavedRecommendations);
  const [favorites, setFavorites] = useState<string[]>(getSavedFavorites);
  const [favSortOrder, setFavSortOrder] = useState<FavSortOrder>(() => (localStorage.getItem('lyricist_fav_sort') as FavSortOrder) || 'newest');
  const [suggestedSongs, setSuggestedSongs] = useState<string[]>(() => getRandomSongs(getSavedRecommendations()));

  // Visibility
  const [isSearchBarVisible, setIsSearchBarVisible] = useState(true);
  const lastScrollY = useRef(0);

  // Settings
  const [theme, setTheme] = useState<'dark' | 'light'>(() => (localStorage.getItem('lyricist_theme') as 'dark' | 'light') || 'dark');
  const [accent, setAccent] = useState<AccentKey>(() => (localStorage.getItem('lyricist_accent') as AccentKey) || 'sky');
  const [customPrimary, setCustomPrimary] = useState(() => localStorage.getItem('lyricist_custom_primary') || '255 0 255');
  const [customSecondary, setCustomSecondary] = useState(() => localStorage.getItem('lyricist_custom_secondary') || '0 255 255');
  const [fontStyle, setFontStyle] = useState<FontStyle>(() => (localStorage.getItem('lyricist_font') as FontStyle) || 'sans');
  const [bgPattern, setBgPattern] = useState<BgPattern>(() => (localStorage.getItem('lyricist_bg') as BgPattern) || 'none');
  const [layoutWidth, setLayoutWidth] = useState<LayoutWidth>(() => (localStorage.getItem('lyricist_width') as LayoutWidth) || 'standard');
  const [cardStyle, setCardStyle] = useState<CardStyle>(() => (localStorage.getItem('lyricist_card') as CardStyle) || 'glass');
  const [blurStrength, setBlurStrength] = useState<BlurStrength>(() => (localStorage.getItem('lyricist_blur') as BlurStrength) || 'medium');
  const [uiScale, setUiScale] = useState<UiScale>(() => parseInt(localStorage.getItem('lyricist_scale') || '100') as UiScale);
  const [animSpeed, setAnimSpeed] = useState<AnimSpeed>(() => (localStorage.getItem('lyricist_anim_speed') as AnimSpeed) || 'normal');
  const [entranceAnim, setEntranceAnim] = useState<EntranceAnim>(() => (localStorage.getItem('lyricist_entrance') as EntranceAnim) || 'cinematic');
  const [bgAnimStyle, setBgAnimStyle] = useState<BgAnimStyle>(() => (localStorage.getItem('lyricist_bg_anim') as BgAnimStyle) || 'rich');
  const [loaderStyle, setLoaderStyle] = useState<LoaderStyle>(() => (localStorage.getItem('lyricist_loader') as LoaderStyle) || 'equalizer');
  const [borderRadius, setBorderRadius] = useState<BorderRadius>(() => (localStorage.getItem('lyricist_radius') as BorderRadius) || 'round');
  const [contentAlign, setContentAlign] = useState<ContentAlign>(() => (localStorage.getItem('lyricist_align') as ContentAlign) || 'center');
  const [searchBarStyle, setSearchBarStyle] = useState<SearchBarStyle>(() => (localStorage.getItem('lyricist_searchbar') as SearchBarStyle) || 'floating');
  const [soundEnabled, setSoundEnabled] = useState(() => localStorage.getItem('lyricist_sound') !== 'false');
  const [hapticEnabled, setHapticEnabled] = useState(() => localStorage.getItem('lyricist_haptic') !== 'false');
  const [reducedMotion, setReducedMotion] = useState(() => localStorage.getItem('lyricist_motion') === 'true');

  // Search
  const [searchState, setSearchState] = useState<SearchState>({ status: 'idle', data: null, error: null });
  const [suggestionsKey, setSuggestionsKey] = useState(0);
  const audioCtxRef = useRef<AudioContext | null>(null);

  // Audio Context
  const getAudioContext = () => {
    if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
    if (audioCtxRef.current.state === 'suspended') audioCtxRef.current.resume();
    return audioCtxRef.current;
  };

  // Sound Engine
  const triggerFeedback = useCallback((type: FeedbackType = 'tap') => {
    if (soundEnabled) {
        try {
            const ctx = getAudioContext();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            const now = ctx.currentTime;
            osc.connect(gain);
            gain.connect(ctx.destination);

            if (type === 'tap' || type === 'light') {
                osc.type = 'sine'; osc.frequency.setValueAtTime(800, now); osc.frequency.exponentialRampToValueAtTime(300, now + 0.05);
                gain.gain.setValueAtTime(0.05, now); gain.gain.exponentialRampToValueAtTime(0.001, now + 0.05);
                osc.start(now); osc.stop(now + 0.05);
            } else if (type === 'toggle') {
                osc.type = 'triangle'; osc.frequency.setValueAtTime(400, now);
                gain.gain.setValueAtTime(0.05, now); gain.gain.linearRampToValueAtTime(0, now + 0.03);
                osc.start(now); osc.stop(now + 0.04);
            } else if (type === 'success') {
                const notes = [523.25, 659.25, 783.99]; 
                notes.forEach((freq, i) => {
                    const o = ctx.createOscillator(); const g = ctx.createGain();
                    o.type = 'sine'; o.frequency.value = freq; o.connect(g); g.connect(ctx.destination);
                    g.gain.setValueAtTime(0, now); g.gain.linearRampToValueAtTime(0.05, now + 0.05 + (i * 0.05));
                    g.gain.exponentialRampToValueAtTime(0.001, now + 0.4 + (i * 0.05));
                    o.start(now + (i * 0.05)); o.stop(now + 0.5 + (i * 0.05));
                });
            } else if (type === 'error') {
                osc.type = 'sawtooth'; osc.frequency.setValueAtTime(150, now); osc.frequency.linearRampToValueAtTime(50, now + 0.3);
                gain.gain.setValueAtTime(0.05, now); gain.gain.linearRampToValueAtTime(0, now + 0.3);
                osc.start(now); osc.stop(now + 0.3);
            } else if (type === 'gamewin') {
                osc.type = 'sine'; osc.frequency.setValueAtTime(200, now); osc.frequency.exponentialRampToValueAtTime(800, now + 0.5);
                gain.gain.setValueAtTime(0.05, now); gain.gain.linearRampToValueAtTime(0, now + 0.5);
                osc.start(now); osc.stop(now + 0.5);
            }
        } catch (e) {}
    }
    if (hapticEnabled && navigator.vibrate) {
        if (type === 'tap' || type === 'light') navigator.vibrate(8);
        else if (type === 'toggle') navigator.vibrate(15);
        else if (type === 'success') navigator.vibrate([10, 30, 10]);
        else if (type === 'error') navigator.vibrate([50, 30, 50]);
        else if (type === 'gamewin') navigator.vibrate([10, 50, 10, 50, 10]);
    }
  }, [soundEnabled, hapticEnabled]);

  // History Sync
  const [history, setHistory] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('lyricist_history');
      if (!saved) return [];
      const parsed = JSON.parse(saved);
      return Array.isArray(parsed) ? parsed.filter((item: any) => typeof item === 'string') : [];
    } catch { return []; }
  });

  useEffect(() => { localStorage.setItem('lyricist_history', JSON.stringify(history)); }, [history]);
  useEffect(() => { localStorage.setItem('lyricist_recommendations', JSON.stringify(recommendationPool)); }, [recommendationPool]);
  useEffect(() => { localStorage.setItem('lyricist_favorites', JSON.stringify(favorites)); }, [favorites]);
  useEffect(() => { localStorage.setItem('lyricist_fav_sort', favSortOrder); }, [favSortOrder]);

  // PWA
  useEffect(() => {
    const handleBeforeInstallPrompt = (e: any) => { e.preventDefault(); setDeferredPrompt(e); };
    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    return () => window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
  }, []);

  // Styles Sync
  useEffect(() => {
    const root = document.documentElement;
    if (theme === 'dark') root.classList.add('dark'); else root.classList.remove('dark');
    if (accent === 'custom') {
        root.style.setProperty('--color-primary', customPrimary);
        root.style.setProperty('--color-secondary', customSecondary);
    } else {
        root.style.setProperty('--color-primary', ACCENT_COLORS[accent].primary);
        root.style.setProperty('--color-secondary', ACCENT_COLORS[accent].secondary);
    }
    const radiusMap = { round: { lg: '1.5rem', sm: '0.75rem' }, soft: { lg: '2rem', sm: '9999px' }, sharp: { lg: '0.25rem', sm: '0.125rem' } };
    root.style.setProperty('--radius', radiusMap[borderRadius].lg);
    root.style.setProperty('--radius-sm', radiusMap[borderRadius].sm);

    if (cardStyle === 'solid') {
        root.style.setProperty('--bg-opacity', '0.95'); root.style.setProperty('--blur', '0px');
        document.body.classList.add('style-solid'); document.body.classList.remove('style-liquid');
    } else if (cardStyle === 'liquid-glass') {
        root.style.setProperty('--bg-opacity', '0.01'); root.style.setProperty('--blur', '0px');
        document.body.classList.add('style-liquid'); document.body.classList.remove('style-solid');
    } else {
        root.style.setProperty('--bg-opacity', theme === 'dark' ? '0.4' : '0.6');
        root.style.setProperty('--blur', blurStrength === 'high' ? '40px' : blurStrength === 'medium' ? '24px' : '12px');
        document.body.classList.remove('style-solid', 'style-liquid');
    }
    root.style.setProperty('--anim-speed', animSpeed === 'slow' ? '1.5' : animSpeed === 'fast' ? '0.6' : '1');
    root.style.fontFamily = { sans: 'Inter, sans-serif', serif: 'Merriweather, serif', mono: 'JetBrains Mono, monospace' }[fontStyle];
    root.style.fontSize = `${uiScale}%`;
    root.style.setProperty('--text-align', contentAlign);
  }, [theme, accent, customPrimary, customSecondary, cardStyle, blurStrength, animSpeed, fontStyle, uiScale, borderRadius, contentAlign]);

  // Scroll
  useEffect(() => {
    const handleScroll = () => {
      const currentScrollY = window.scrollY;
      if (currentScrollY <= 50) setIsSearchBarVisible(true);
      else setIsSearchBarVisible(currentScrollY <= lastScrollY.current);
      lastScrollY.current = currentScrollY;
    };
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Search Logic
  const handleSearch = async (query: string) => {
    if (!query.trim()) return;
    try {
        const url = new URL(window.location.href); url.searchParams.set('q', query); window.history.pushState({}, '', url);
    } catch (e) {}
    setSearchState(prev => ({ ...prev, status: 'loading', error: null }));
    if (!history.includes(query)) setHistory([query, ...history].slice(0, 10));
    try {
      const result = await fetchLyrics(query);
      setSearchState({ status: 'success', data: result, error: null });
      triggerFeedback('success');
      let newRecs = [...recommendationPool];
      if (result.metadata?.title && result.metadata?.artist) {
          const k = `${result.metadata.title} - ${result.metadata.artist}`;
          if (!newRecs.includes(k)) newRecs.unshift(k);
      }
      if (result.metadata?.relatedSongs) {
          result.metadata.relatedSongs.forEach(s => { if (!newRecs.includes(s)) newRecs.unshift(s); });
      }
      setRecommendationPool(newRecs.slice(0, 50));
    } catch (err: any) {
      setSearchState({ status: 'error', data: null, error: err.message });
      triggerFeedback('error');
    }
  };

  const handleFavoriteToggle = (song: string) => {
      setFavorites(favorites.includes(song) ? favorites.filter(f => f !== song) : [song, ...favorites]);
      triggerFeedback('toggle');
  };

  const resetApp = () => {
    setSearchState({ status: 'idle', data: null, error: null });
    setSearchQuery(''); setSuggestionsKey(prev => prev + 1);
    try { const url = new URL(window.location.href); url.searchParams.delete('q'); window.history.pushState({}, '', url); } catch(e) {}
    triggerFeedback('tap');
  };

  const getSortedFavorites = () => {
      const s = [...favorites];
      switch (favSortOrder) {
          case 'az': return s.sort(); case 'za': return s.sort().reverse();
          case 'oldest': return s.reverse(); default: return s;
      }
  };

  // --- Arcade Game Logic ---
  const generateQuestion = useCallback(() => {
    // Determine difficulty based on level
    let pool = SONG_POOL;
    if (gameLevel > 2) pool = [...pool, ...recommendationPool]; 
    if (gameLevel > 5) pool = recommendationPool.length > 10 ? recommendationPool : pool;

    // Filter out played questions
    const available = pool.filter(s => !playedQuestions.has(s));

    // If no questions left, recycle but warn or clear
    let targetSong = "";
    if (available.length === 0) {
       // Just pick random if exhausted
       targetSong = pool[Math.floor(Math.random() * pool.length)];
    } else {
       targetSong = available[Math.floor(Math.random() * available.length)];
    }

    const [title, artist] = targetSong.split(' - ');
    if (!title || !artist) return; // Skip invalid formats

    // Distractors
    let options = [artist];
    let attempts = 0;
    while (options.length < 4 && attempts < 20) {
        attempts++;
        const r = SONG_POOL[Math.floor(Math.random() * SONG_POOL.length)];
        const a = r.split(' - ')[1];
        if (a && !options.includes(a)) options.push(a);
    }
    // Fill with generic if needed
    while(options.length < 4) {
       options.push("Unknown Artist " + options.length);
    }

    setCurrentQuestion({ song: title, correct: artist, options: options.sort(() => 0.5 - Math.random()) });
    setPlayedQuestions(prev => new Set(prev).add(targetSong));
  }, [gameLevel, recommendationPool, playedQuestions]);

  const handleAnswer = (selected: string) => {
    if (!currentQuestion) return;
    if (selected === currentQuestion.correct) {
        // Correct
        setGameScore(prev => prev + 10 * (streak + 1));
        setStreak(prev => prev + 1);
        setQuestionsCorrect(prev => prev + 1);
        setGameTimer(prev => Math.min(prev + 5, 60)); // Time Bonus
        triggerFeedback('success');

        if ((questionsCorrect + 1) % 5 === 0) {
            setGameLevel(prev => prev + 1);
            setGameTimer(prev => Math.min(prev + 10, 60)); // Level up bonus
            triggerFeedback('gamewin');
        }
        generateQuestion();
    } else {
        // Incorrect
        setStreak(0);
        setGameTimer(prev => Math.max(0, prev - 10)); // Time Penalty
        triggerFeedback('error');
        if (gameTimer - 10 <= 0) setGameState('gameover');
    }
    setRemovedOptions([]); // Reset powerup
  };

  const usePowerup = (type: 'split' | 'freeze') => {
      if (powerups[type] > 0) {
          setPowerups(prev => ({...prev, [type]: prev[type] - 1}));
          triggerFeedback('gamewin');
          if (type === 'split' && currentQuestion) {
              const wrong = currentQuestion.options.filter(o => o !== currentQuestion.correct);
              setRemovedOptions(wrong.slice(0, 2));
          } else if (type === 'freeze') {
              setIsFrozen(true);
              setTimeout(() => setIsFrozen(false), 5000);
          }
      }
  };

  // Game Timer
  useEffect(() => {
    let interval: any;
    if (isEggGameOpen && gameState === 'playing' && !isFrozen) {
        interval = setInterval(() => {
            setGameTimer(prev => {
                if (prev <= 1) {
                    setGameState('gameover');
                    triggerFeedback('error');
                    return 0;
                }
                return prev - 1;
            });
        }, 1000);
    }
    return () => clearInterval(interval);
  }, [isEggGameOpen, gameState, isFrozen, triggerFeedback]);

  // Start Game
  useEffect(() => {
      if (isEggGameOpen && gameState === 'playing' && !currentQuestion) {
          generateQuestion();
      }
  }, [isEggGameOpen, gameState, currentQuestion, generateQuestion]);


  return (
    <div className={`min-h-[100dvh] transition-colors duration-700 ease-in-out font-sans ${bgPattern === 'grid' ? 'bg-pattern-grid' : bgPattern === 'dots' ? 'bg-pattern-dots' : ''} ${cardStyle === 'liquid-glass' ? 'overflow-x-hidden' : ''}`}>

      {bgAnimStyle !== 'minimal' && !reducedMotion && (
        <div className="fixed inset-0 z-0 overflow-hidden pointer-events-none">
            {bgAnimStyle === 'rich' && (
                <>
                <div className="absolute top-0 left-1/4 w-[500px] h-[500px] bg-primary/20 dark:bg-primary/10 rounded-full mix-blend-screen dark:mix-blend-screen blur-[120px] animate-blob filter"></div>
                <div className="absolute top-0 right-1/4 w-[500px] h-[500px] bg-secondary/20 dark:bg-secondary/10 rounded-full mix-blend-screen dark:mix-blend-screen blur-[120px] animate-blob animation-delay-2000 filter"></div>
                </>
            )}
        </div>
      )}

      <div className={`relative z-10 flex flex-col min-h-[100dvh] ${layoutWidth === 'narrow' ? 'max-w-3xl' : layoutWidth === 'wide' ? 'max-w-[1600px]' : 'max-w-6xl'} mx-auto px-4 md:px-8`}>
        <header className="pt-8 pb-6 flex flex-col items-center justify-center text-center cursor-pointer transition-transform active:scale-95 ease-silky" onClick={() => { if (searchState.status === 'idle') { setEggClicks(prev => prev + 1); if (eggClicks + 1 === 5) { setIsEggGameOpen(true); setGameState('playing'); setGameTimer(30); setEggClicks(0); triggerFeedback('gamewin'); } else triggerFeedback('tap'); } else resetApp(); }}>
          <h1 className="text-4xl md:text-6xl font-black tracking-tighter mb-2 bg-clip-text text-transparent bg-gradient-to-r from-primary via-secondary to-primary animate-gradient-xy bg-[length:200%_auto]">Lyricist</h1>
          <p className="text-zinc-500 dark:text-zinc-400 text-sm font-medium tracking-wide">Exact Lyrics Finder</p>
        </header>

        <main className="flex-1 flex flex-col items-center w-full pb-40">
          {searchState.status === 'idle' && (
            <>
              <SongSuggestions key={suggestionsKey} songs={suggestedSongs} onSelect={(q) => { setSearchQuery(q); handleSearch(q); }} />
              <SearchHistory history={history} onSelect={(q) => { setSearchQuery(q); handleSearch(q); }} onClear={() => { setHistory([]); localStorage.removeItem('lyricist_history'); triggerFeedback('tap'); }} />
            </>
          )}

          {searchState.status === 'loading' && (
            <div className="flex flex-col items-center justify-center min-h-[70vh] animate-fade-in">
              {loaderStyle === 'equalizer' ? (
                  <div className="flex items-end justify-center gap-1 h-[3.25rem] mb-4">
                    {[...Array(9)].map((_, i) => (
                        <div key={i} className="w-1.5 bg-gradient-to-t from-primary to-secondary rounded-full animate-wave shadow-[0_0_10px_rgba(var(--color-primary),0.4)]" style={{ animationDelay: `${i * 0.1}s`, height: '100%' }}></div>
                    ))}
                  </div>
              ) : (
                  <div className="relative w-16 h-16 mb-4 animate-spin"><div className="absolute top-0 left-0 w-full h-full border-4 border-zinc-200 dark:border-white/10 rounded-full"></div><div className="absolute top-0 left-0 w-full h-full border-4 border-primary rounded-full border-t-transparent animate-spin"></div></div>
              )}
              <p className="text-zinc-400 dark:text-zinc-500 font-medium animate-pulse text-sm">Loading...</p>
            </div>
          )}

          {searchState.status === 'success' && searchState.data && (
            <LyricsDisplay data={searchState.data} onSearch={handleSearch} isKaraokeMode={isKaraokeMode} setIsKaraokeMode={(v) => { setIsKaraokeMode(v); triggerFeedback(v ? 'gamewin' : 'tap'); }} entranceAnim={entranceAnim} favorites={favorites} onToggleFavorite={handleFavoriteToggle} triggerFeedback={triggerFeedback} />
          )}

          {searchState.status === 'error' && (
            <div className="text-center mt-12 p-8 bg-red-50 dark:bg-red-900/10 border border-red-100 dark:border-red-900/20 rounded-[var(--radius)] animate-zoom-in max-w-lg">
              <h2 className="text-xl font-bold text-red-600 dark:text-red-400 mb-2">Oops!</h2>
              <p className="text-zinc-600 dark:text-zinc-300">{searchState.error}</p>
              <button onClick={resetApp} className="mt-6 px-6 py-2 bg-red-600 hover:bg-red-700 text-white font-medium rounded-full transition-all hover:scale-105 active:scale-95 ease-silky">Try Again</button>
            </div>
          )}
        </main>

        {!isKaraokeMode && (
            <div className={`fixed bottom-0 left-0 right-0 z-50 p-4 pb-6 transition-transform duration-500 ease-silky ${isSearchBarVisible ? 'translate-y-0' : 'translate-y-full'}`}>
                <div className="absolute inset-0 bg-gradient-to-t from-white via-white/90 to-transparent dark:from-black dark:via-black/90 dark:to-transparent pointer-events-none h-32 -top-16"></div>
                <SearchBar query={searchQuery} setQuery={setSearchQuery} onSearch={handleSearch} isLoading={searchState.status === 'loading'} style={searchBarStyle} />
            </div>
        )}
      </div>

      {!isKaraokeMode && (
          <>
            <button onClick={() => { if (searchState.status === 'idle') { setSuggestionsKey(p => p + 1); triggerFeedback('success'); } else resetApp(); }} className={`fixed top-6 left-6 z-40 p-3 rounded-full bg-white/[var(--bg-opacity)] dark:bg-black/[var(--bg-opacity)] backdrop-blur-[var(--blur)] shadow-lg border border-zinc-200 dark:border-white/10 text-zinc-600 dark:text-zinc-400 hover:text-primary transition-all duration-500 ease-silky hover:scale-110 active:scale-90 ${isSearchBarVisible ? 'translate-y-0 opacity-100' : '-translate-y-20 opacity-0'}`}>
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6" /></svg>
            </button>
            <button onClick={() => { setIsSettingsOpen(true); triggerFeedback('tap'); }} className={`fixed top-6 right-6 z-40 p-3 rounded-full bg-white/[var(--bg-opacity)] dark:bg-black/[var(--bg-opacity)] backdrop-blur-[var(--blur)] shadow-lg border border-zinc-200 dark:border-white/10 text-zinc-600 dark:text-zinc-400 hover:text-primary transition-all duration-500 ease-silky hover:rotate-90 hover:scale-110 active:scale-90 ${isSearchBarVisible ? 'translate-y-0 opacity-100' : '-translate-y-20 opacity-0'}`}>
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
            </button>
          </>
      )}

      {/* Settings Modal */}
      {isSettingsOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm animate-fade-in" onClick={() => setIsSettingsOpen(false)}>
            <div className="w-full max-w-4xl h-[80vh] flex flex-col md:flex-row rounded-[var(--radius)] overflow-hidden animate-zoom-in bg-white/[var(--bg-opacity)] dark:bg-black/[var(--bg-opacity)] backdrop-blur-[var(--blur)] shadow-2xl border border-white/20" onClick={e => e.stopPropagation()}>
                <div className="w-full md:w-64 bg-zinc-50/50 dark:bg-white/5 border-r border-zinc-200 dark:border-white/5 flex flex-col">
                    <div className="p-6 border-b border-zinc-200 dark:border-white/5"><h2 className="text-xl font-black text-zinc-900 dark:text-white tracking-tight">Settings</h2></div>
                    <nav className="flex-1 p-4 space-y-2 overflow-y-auto">
                        <button onClick={() => setActiveSettingsTab('appearance')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-all ease-silky ${activeSettingsTab === 'appearance' ? 'bg-primary text-white shadow-lg shadow-primary/30' : 'text-zinc-600 dark:text-zinc-400 hover:bg-zinc-200 dark:hover:bg-white/10'}`}>Appearance</button>
                        <button onClick={() => setActiveSettingsTab('general')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-all ease-silky ${activeSettingsTab === 'general' ? 'bg-primary text-white shadow-lg shadow-primary/30' : 'text-zinc-600 dark:text-zinc-400 hover:bg-zinc-200 dark:hover:bg-white/10'}`}>General</button>
                        <button onClick={() => setActiveSettingsTab('system')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-all ease-silky ${activeSettingsTab === 'system' ? 'bg-primary text-white shadow-lg shadow-primary/30' : 'text-zinc-600 dark:text-zinc-400 hover:bg-zinc-200 dark:hover:bg-white/10'}`}>System</button>
                        <button onClick={() => setActiveSettingsTab('favorites')} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-all ease-silky ${activeSettingsTab === 'favorites' ? 'bg-primary text-white shadow-lg shadow-primary/30' : 'text-zinc-600 dark:text-zinc-400 hover:bg-zinc-200 dark:hover:bg-white/10'}`}>Favorites</button>
                    </nav>
                    <div className="p-6 border-t border-zinc-200 dark:border-white/5"><p className="text-xs text-center text-zinc-400">v2.1.0 • Built with Gemini</p><p className="text-xs text-center font-bold text-transparent bg-clip-text bg-gradient-to-r from-primary to-secondary mt-1">Saisriram Sr</p></div>
                </div>
                <div className="flex-1 bg-transparent p-6 overflow-y-auto custom-scrollbar">
                    {activeSettingsTab === 'appearance' && (
                        <div className="space-y-8 animate-fade-in">
                            <section><h3 className="text-lg font-bold text-zinc-900 dark:text-white mb-4">Theme & Color</h3><div className="p-4 bg-white/50 dark:bg-white/5 rounded-2xl border border-zinc-200 dark:border-white/5"><SegmentedControl options={['dark', 'light']} value={theme} onChange={(v) => { setTheme(v); localStorage.setItem('lyricist_theme', v); }} label="Theme Mode" /><div className="mt-4"><span className="block text-xs font-bold text-zinc-400 uppercase mb-2">Accent Color</span><div className="flex flex-wrap gap-2">{Object.entries(ACCENT_COLORS).map(([key, val]) => (<button key={key} onClick={() => { setAccent(key as AccentKey); localStorage.setItem('lyricist_accent', key); }} className={`w-8 h-8 rounded-full transition-transform hover:scale-110 ${accent === key ? 'ring-2 ring-offset-2 ring-offset-black ring-white scale-110' : ''}`} style={{ background: `rgb(${val.primary})` }} />))}<button onClick={() => { setAccent('custom'); localStorage.setItem('lyricist_accent', 'custom'); }} className={`w-8 h-8 rounded-full transition-transform hover:scale-110 flex items-center justify-center bg-gradient-to-tr from-red-500 via-green-500 to-blue-500 ${accent === 'custom' ? 'ring-2 ring-offset-2 ring-offset-black ring-white scale-110' : ''}`}><span className="text-[10px] text-white font-bold">+</span></button></div></div>{accent === 'custom' && (<div className="mt-4 grid grid-cols-1 md:grid-cols-2 gap-4 animate-slide-up-fade"><ColorWheelPicker label="Primary Color" rgbValue={customPrimary} onChange={(rgb) => { setCustomPrimary(rgb); localStorage.setItem('lyricist_custom_primary', rgb); }} /><ColorWheelPicker label="Secondary Color" rgbValue={customSecondary} onChange={(rgb) => { setCustomSecondary(rgb); localStorage.setItem('lyricist_custom_secondary', rgb); }} /></div>)}</div></section>
                            <section><h3 className="text-lg font-bold text-zinc-900 dark:text-white mb-4">Interface Style</h3><div className="p-4 bg-white/50 dark:bg-white/5 rounded-2xl border border-zinc-200 dark:border-white/5 space-y-4"><SegmentedControl options={['glass', 'solid', 'liquid-glass']} value={cardStyle} onChange={(v) => { setCardStyle(v); localStorage.setItem('lyricist_card', v); }} label="Card Material" /><SegmentedControl options={['round', 'soft', 'sharp']} value={borderRadius} onChange={(v) => { setBorderRadius(v); localStorage.setItem('lyricist_radius', v); }} label="Corner Shape" /><SegmentedControl options={['floating', 'docked', 'minimal']} value={searchBarStyle} onChange={(v) => { setSearchBarStyle(v); localStorage.setItem('lyricist_searchbar', v); }} label="Search Bar Style" /></div></section>
                        </div>
                    )}
                    {activeSettingsTab === 'favorites' && (
                        <div className="space-y-4 animate-fade-in">
                            <div className="flex justify-between items-center mb-4"><h3 className="text-lg font-bold text-zinc-900 dark:text-white">Your Library</h3><select value={favSortOrder} onChange={(e) => setFavSortOrder(e.target.value as FavSortOrder)} className="bg-zinc-100 dark:bg-zinc-800 text-xs font-bold uppercase rounded-lg px-3 py-2 border-none"><option value="newest">Newest First</option><option value="oldest">Oldest First</option><option value="az">A-Z</option><option value="za">Z-A</option></select></div>
                            <div className="space-y-4 p-6 bg-white/50 dark:bg-white/5 rounded-3xl border border-zinc-200 dark:border-white/5">
                                {favorites.length === 0 ? <p className="text-center text-zinc-500 py-8">No favorites yet.</p> : getSortedFavorites().map((fav) => {
                                    const [title, artist] = fav.split(' - ');
                                    return (
                                        <div key={fav} className="flex items-center justify-between p-5 bg-white dark:bg-white/5 rounded-2xl border border-zinc-100 dark:border-white/5 hover:border-primary/50 transition-all group">
                                            <div onClick={() => { setIsSettingsOpen(false); handleSearch(fav); }} className="cursor-pointer flex-1"><h4 className="font-bold text-zinc-900 dark:text-white">{title}</h4><p className="text-xs text-zinc-500">{artist}</p></div>
                                            <button onClick={() => handleFavoriteToggle(fav)} className="p-2 text-red-500 hover:bg-red-500/10 rounded-full"><svg className="w-5 h-5 fill-current" viewBox="0 0 24 24"><path d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z"/></svg></button>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>
      )}

      {/* Arcade Game Overlay */}
      {isEggGameOpen && (
        <div className="fixed inset-0 z-[200] bg-black text-white bg-scanlines font-mono flex flex-col items-center justify-center overflow-hidden">
            <div className="absolute inset-0 bg-gradient-to-b from-transparent to-primary/10 pointer-events-none"></div>
            {gameState === 'playing' && currentQuestion ? (
                <div className="w-full max-w-2xl p-8 relative z-10 animate-zoom-in">
                    <div className="flex justify-between items-end mb-8 border-b-2 border-primary pb-4">
                        <div><p className="text-xs text-primary mb-1">SCORE</p><p className="text-4xl font-black glitch-text">{gameScore.toString().padStart(6, '0')}</p></div>
                        <div className="text-center"><p className="text-xs text-zinc-400">LEVEL {gameLevel}</p><div className="w-32 h-2 bg-zinc-800 rounded-full mt-1 overflow-hidden"><div className="h-full bg-primary transition-all duration-500" style={{ width: `${(questionsCorrect % 5) * 20}%` }}></div></div></div>
                        <div className="text-right"><p className="text-xs text-red-500 mb-1">TIME</p><p className={`text-4xl font-black ${gameTimer < 10 ? 'text-red-500 animate-pulse' : 'text-white'}`}>{gameTimer}s</p></div>
                    </div>
                    <div className="mb-12 text-center">
                        <p className="text-sm text-zinc-500 mb-2 uppercase tracking-widest">Identify The Artist</p>
                        <h2 className="text-4xl md:text-5xl font-black text-white mb-8 drop-shadow-[0_0_10px_rgba(255,255,255,0.5)]">{currentQuestion.song}</h2>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            {currentQuestion.options.map((opt) => (
                                <button key={opt} disabled={removedOptions.includes(opt)} onClick={() => handleAnswer(opt)} className={`p-6 border-2 ${removedOptions.includes(opt) ? 'border-zinc-800 text-zinc-700 opacity-50 cursor-not-allowed' : 'border-primary/50 hover:border-primary hover:bg-primary/20 text-white'} rounded-xl font-bold text-xl transition-all active:scale-95 uppercase tracking-wide backdrop-blur-sm relative overflow-hidden group`}>
                                    <span className="relative z-10">{opt}</span>
                                    <div className="absolute inset-0 bg-primary/10 translate-y-full group-hover:translate-y-0 transition-transform duration-300"></div>
                                </button>
                            ))}
                        </div>
                    </div>
                    <div className="flex justify-center gap-4">
                        <button onClick={() => usePowerup('split')} disabled={powerups.split === 0} className={`px-4 py-2 border border-zinc-700 rounded-lg text-xs font-bold uppercase ${powerups.split > 0 ? 'hover:bg-white/10 text-white' : 'opacity-30 text-zinc-500'}`}>50/50 ({powerups.split})</button>
                        <button onClick={() => usePowerup('freeze')} disabled={powerups.freeze === 0} className={`px-4 py-2 border border-zinc-700 rounded-lg text-xs font-bold uppercase ${powerups.freeze > 0 ? 'hover:bg-white/10 text-white' : 'opacity-30 text-zinc-500'}`}>Freeze ({powerups.freeze})</button>
                    </div>
                </div>
            ) : (
                <div className="text-center p-8 animate-zoom-in relative z-10">
                    <h2 className="text-6xl font-black text-red-500 mb-4 glitch-text">GAME OVER</h2>
                    <p className="text-2xl text-white mb-8">Final Score: {gameScore}</p>
                    <button onClick={() => { setIsEggGameOpen(false); setGameState('playing'); setGameScore(0); setGameTimer(30); setGameLevel(1); setPlayedQuestions(new Set()); triggerFeedback('tap'); }} className="px-8 py-4 bg-white text-black font-black text-xl uppercase rounded-full hover:scale-110 transition-transform">Main Menu</button>
                </div>
            )}
        </div>
      )}
    </div>
  );
};

export default App;
